// Runs the orrery's trajectory search (trajsearch.js, copied unchanged from commit a4ea6e3) off the page's main thread,
// on astronomy-engine states, as the page's porkchop does. Generated by portfolio/figures/orrery/build_porkchop.py.
import * as A from "https://cdn.jsdelivr.net/npm/astronomy-engine@2.1.19/esm/astronomy.js";
import { searchTransfers } from "./trajsearch.js";
const AU = 149597870.7, AUD = AU / 86400, R = A.Rotation_EQJ_ECL();
const BODY = { venus: A.Body.Venus, earth: A.Body.Earth, mars: A.Body.Mars, jupiter: A.Body.Jupiter };
const stateOf = (k, d) => { const s = A.RotateState(R, A.HelioState(BODY[k], d)); return { r: [s.x * AU, s.y * AU, s.z * AU], v: [s.vx * AUD, s.vy * AUD, s.vz * AUD] }; };
self.onmessage = (e) => {
  const t0 = performance.now();
  const r = searchTransfers({ stateOf, ...e.data });
  self.postMessage({ to: e.data.to, optima: r.optima, evaluated: r.evaluated, ms: Math.round(performance.now() - t0) });
};
